LESSONS.append({
    "id": "duowei-cheng-yiwei",
    "file": "lesson-duowei-cheng-yiwei.html",
    "stage": "xiaoxue",
    "grade": "三年级",
    "title": "多位数乘一位数",
    "subtitle": "从个位乘起，满几十就进几",
    "brief": "三箱牛奶，每箱 24 盒。24 × 3 可以拆成 20 × 3 + 4 × 3 口算，也可以列竖式。学会进位，两三位数乘一位数都不怕。",
    "minutes": 9,
    "difficulty": 2,
    "tags": ["数的运算", "乘法", "进位"],
    "video": "assets/videos/duowei-cheng-yiwei.mp4",
    "videoNote": "视频里进位的小数字会先亮一下再写上去。注意 128 × 4 这一节：个位、十位、百位各进了一次位。",
    "keyformula": "满几十，向前一位进几",
    "goals": [
        "会把两位数拆成整十数加个位数来口算",
        "会列竖式计算多位数乘一位数",
        "理解进位：哪一位满几十，就向前一位进几",
        "会处理连续进位和末尾有 0 的乘法",
    ],
    "chapters": [
        "三箱牛奶，一共多少盒",
        "口算：先拆成 20 和 4",
        "竖式：从个位开始乘",
        "进位：满几十，进几",
        "连续进位：128 × 4",
        "末尾有 0：先算再添 0",
        "竖式三步，记住就不会错",
    ],
    "knowledge": [
        {
            "kind": "concept",
            "title": "口算：先拆成整十数和个位数",
            "body": [
                "24 × 3 表示 3 个 24 相加。直接加太慢，把 24 拆成 20 和 4，分别乘 3，再把结果合起来。",
                "20 × 3 = 60，4 × 3 = 12，60 + 12 = 72。所以 24 × 3 = 72。这个方法对任何两位数都适用。",
            ],
        },
        {
            "kind": "formula",
            "title": "竖式：数位对齐，从个位乘起",
            "body": [
                "列竖式时，把一位数写在多位数的下面，末位对齐，乘号写在左边，下面画一条横线。",
                "计算时用一位数依次去乘多位数的每一位，从个位开始。3 × 4 = 12，个位写 2，向十位进 1；3 × 2 = 6，再加进位 1 得 7。",
            ],
            "formula": "24 × 3 = 72",
        },
        {
            "kind": "concept",
            "title": "进位：满几十，向前一位进几",
            "body": [
                "哪一位乘得的积满几十，就向前一位进几。3 × 4 = 12，满 10，向十位进 1；如果积是 32，就向十位进 3。",
                "进位的数字要写小一点，标在前一位的右下角，计算前一位时先把它加上，最后别忘了检查有没有漏加。",
            ],
        },
        {
            "kind": "example",
            "title": "连续进位与末尾有 0",
            "body": [
                "128 × 4：4 × 8 = 32，写 2 进 3；4 × 2 = 8，8 + 3 = 11，写 1 进 1；4 × 1 = 4，4 + 1 = 5。结果是 512。",
                "末尾有 0 时，先不管 0：240 × 3，先算 24 × 3 = 72，再在末尾添一个 0，得 720。",
            ],
        },
    ],
    "pitfalls": [
        "从高位开始乘：竖式必须从个位乘起，否则进位无处可写。",
        "忘记加进位：算出 3 × 2 = 6 就写 6，漏了进位的 1，正确答案应是 7。",
        "数位没对齐：把一位数写在十位下面，结果会整体错位。",
        "末尾的 0 丢掉：240 × 3 算成 72，忘了添 0，应该是 720。",
    ],
    "summary": "多位数乘一位数：数位对齐，从个位乘起；哪一位满几十就向前一位进几，进位的数要记住加上。末尾有 0 时，先算前面的数，再在末尾添 0。",
    "questions": [
        {
            "prompt": "计算 24 × 3 时，3 × 4 = 12，个位写 2，应该向十位进几？",
            "options": ["1", "2", "3"],
            "answer": 0,
            "explanation": "12 里面有一个十，所以向十位进 1。如果积是 32，就进 3。",
        },
        {
            "prompt": "128 × 4 的结果是多少？",
            "options": ["412", "512", "482"],
            "answer": 1,
            "explanation": "4 × 8 = 32 写 2 进 3；4 × 2 = 8，8 + 3 = 11 写 1 进 1；4 × 1 = 4，4 + 1 = 5，得 512。",
        },
        {
            "prompt": "240 × 3 的结果是多少？",
            "options": ["620", "720", "702"],
            "answer": 1,
            "explanation": "先算 24 × 3 = 72，再在末尾添一个 0，得 720。",
        },
        {
            "prompt": "列竖式计算多位数乘一位数，应该从哪一位开始乘？",
            "options": ["个位", "十位", "最高位"],
            "answer": 0,
            "explanation": "从个位乘起，进位的数才能依次向前一位传递。从高位开始乘，进位就无处安放。",
        },
    ],
})

