LESSONS.append({
    "id": "yun-suanlv",
    "file": "lesson-yun-suanlv.html",
    "stage": "xiaoxue",
    "grade": "四年级",
    "title": "运算律：怎么算更快",
    "subtitle": "换顺序、换分组，结果不变",
    "brief": "同样一批椅子，四行六把和六行四把都是 24 把。加法、乘法都有交换律和结合律，乘法还多一条分配律。学会它们，25×4、125×8、99×26 这类题可以直接口算。",
    "minutes": 10,
    "difficulty": 3,
    "tags": ["数与代数", "运算律", "简便计算", "分配律"],
    "video": "assets/videos/yun-suanlv.mp4",
    "videoNote": "第 4 节用长方形面积讲分配律：(4+6)×25 就是两个小长方形的面积相加。第 6 节专门提醒：分配律只管加和减，25×(4×8) 不能拆成 25×4+25×8。",
    "keyformula": "先凑整，再计算",
    "goals": [
        "理解并会用加法交换律、加法结合律",
        "理解并会用乘法交换律、乘法结合律",
        "理解乘法分配律，会正着拆、反着合",
        "记住 25×4=100、125×8=1000 两对好朋友",
        "会把 99、101 拆成 100−1、100+1 再简算",
        "知道减法和除法没有交换律，分配律只管加减",
    ],
    "chapters": [
        "四行六把，六行四把",
        "加法交换律、结合律",
        "乘法交换律、结合律",
        "乘法分配律：拆开算",
        "看到 25 找 4，看到 125 找 8",
        "分配律只对加减管用",
        "五个运算律，一句话",
    ],
    "knowledge": [
        {
            "kind": "concept",
            "title": "加法交换律、结合律",
            "body": [
                "加法交换律：两个数相加，交换加数的位置，和不变，a + b = b + a。",
                "加法结合律：三个数相加，先把前两个相加，或者先把后两个相加，和不变，(a + b) + c = a + (b + c)。先算能凑成整百的那两个，计算就快。",
            ],
        },
        {
            "kind": "concept",
            "title": "乘法交换律、结合律",
            "body": [
                "乘法交换律：两个数相乘，交换因数的位置，积不变，a × b = b × a。",
                "乘法结合律：三个数相乘，先乘前两个或先乘后两个，积不变，(a × b) × c = a × (b × c)。17×2×5 先算 2×5 = 10，再乘 17 就得 170。",
            ],
        },
        {
            "kind": "formula",
            "title": "乘法分配律",
            "body": [
                "两个数的和（或差）乘一个数，可以先把它们分别乘这个数，再相加（或相减）：(a + b) × c = a × c + b × c。",
                "反过来也成立：a × c + b × c = (a + b) × c，这就是提取公因数。注意分配律只管加和减，乘法对乘法不能分配。",
            ],
            "formula": "(a+b)×c = a×c+b×c",
        },
        {
            "kind": "example",
            "title": "简便计算：凑整与拆分",
            "body": [
                "25 和 4 是好朋友，乘起来正好 100；125 和 8 是好朋友，乘起来正好 1000。看到 25 就找 4，看到 125 就找 8。",
                "99 × 26 = (100 − 1) × 26 = 2600 − 26 = 2574；101 × 26 = (100 + 1) × 26 = 2600 + 26 = 2626。把接近整百的数拆开，再用分配律。",
            ],
        },
    ],
    "pitfalls": [
        "分配律用错对象：25 × (4 × 8) 不能拆成 25×4 + 25×8，只有括号里是加减才能分配。",
        "只乘了一个数：25 × (4 + 8) 写成 25×4 + 8，忘了给 8 也乘 25。",
        "减法、除法乱用交换律：8 − 3 ≠ 3 − 8，8 ÷ 2 ≠ 2 ÷ 8。",
        "结合律和分配律混了：17×2×5 用结合律先算 2×5，不是把 17 分别乘。",
        "凑整凑错方向：99 拆成 100 − 1 后，别忘了最后要减 26，不是加 26。",
    ],
    "summary": "加法和乘法都有交换律、结合律，乘法还多一条分配律。简便计算先看数字特点：25 找 4、125 找 8、99 想 100−1、101 想 100+1。分配律只管加减，乘法和除法不能乱分配。",
    "questions": [
        {
            "prompt": "用乘法分配律计算 25 × (4 + 8)，等于下面哪个式子？",
            "options": ["25 × 4 + 25 × 8", "25 × 4 × 25 × 8", "25 × 4 + 8"],
            "answer": 0,
            "explanation": "分配律要把括号里的每个数都乘 25：(4 + 8) × 25 = 4×25 + 8×25，不能只乘一个。",
        },
        {
            "prompt": "125 × 8 等于多少？",
            "options": ["100", "1000", "800"],
            "answer": 1,
            "explanation": "125 和 8 是一对好朋友，125 × 8 = 1000，遇到 125 就找 8。",
        },
        {
            "prompt": "下面哪个等式一定成立？",
            "options": ["8 − 3 = 3 − 8", "8 ÷ 2 = 2 ÷ 8", "35 + 65 = 65 + 35"],
            "answer": 2,
            "explanation": "加法交换律成立；减法和除法没有交换律，8−3=5 而 3−8 不是 5，8÷2=4 而 2÷8 不是 4。",
        },
        {
            "prompt": "计算 17 × 2 × 5，先算哪两个最简便？",
            "options": ["17 × 2", "2 × 5", "17 × 5"],
            "answer": 1,
            "explanation": "先用乘法结合律算 2 × 5 = 10，再算 17 × 10 = 170，比先算 17×2 简单。",
        },
    ],
})

LESSONS.append({
    "id": "xiaoshu-cheng",
    "file": "lesson-xiaoshu-cheng.html",
    "stage": "xiaoxue",
    "grade": "四年级",
    "title": "小数乘法",
    "subtitle": "先按整数乘，再点小数点",
    "brief": "一支笔 2.5 元买 3 支，一袋苹果 6 元一千克买 0.8 千克——生活里买东西，价钱常常带小数。小数乘法只要记住三句话：先按整数乘，数一数两个因数一共有几位小数，再从右往左点小数点。",
    "minutes": 10,
    "difficulty": 3,
    "tags": ["数与代数", "小数", "乘法", "小数点"],
    "video": "assets/videos/xiaoshu-cheng.mp4",
    "videoNote": "第 3 节算 0.02×0.3：2×3 只有一位数，但小数位数有三位，要在前面补两个 0 写成 0.006，少补一个就错十倍。第 5 节用估算检查小数点：2.9×4.1 约等于 3×4=12，算成 118.9 一看就知道错了。",
    "keyformula": "先按整数乘",
    "goals": [
        "理解小数乘法的算理：先按整数乘，再按小数位数点小数点",
        "会算小数乘整数，比如 2.5×3",
        "会算小数乘小数，两个因数的小数位数相加就是积的小数位数",
        "位数不够时知道在前面补 0 占位",
        "知道积末尾的 0 可以去掉，中间的 0 不能去",
        "会用估算检查小数点有没有点错",
    ],
    "chapters": [
        "一支笔 2.5 元，买 3 支",
        "先按整数乘，再点小数点",
        "小数乘小数：两位小数怎么点",
        "位数不够，前面补零",
        "末尾的 0 能去，中间的不能去",
        "先估算，再检查小数点",
        "小数乘法三句话",
    ],
    "knowledge": [
        {
            "kind": "concept",
            "title": "小数乘整数",
            "body": [
                "2.5 × 3：先把 2.5 看成 25，25 × 3 = 75。因为 2.5 是一位小数，相当于把 25 缩小了 10 倍，所以积也要缩小 10 倍，75 变成 7.5。",
                "一句话：先按整数乘，再看因数里有几位小数，积就点几位小数。",
            ],
        },
        {
            "kind": "formula",
            "title": "小数乘小数",
            "body": [
                "2.4 × 1.3：先算 24 × 13 = 312。两个因数一共有 1 + 1 = 2 位小数，就从 312 的右边往左数两位点上小数点，得 3.12。",
                "两个因数的小数位数相加，就是积的小数位数。这个方法对所有小数乘法都成立。",
            ],
            "formula": "位数相加再点小数点",
        },
        {
            "kind": "example",
            "title": "补零与去零",
            "body": [
                "0.02 × 0.3：2 × 3 = 6，两个因数一共 2 + 1 = 3 位小数，可 6 只有一位，位数不够就在前面补 0，写成 0.006。少补一个零就差十倍。",
                "0.5 × 0.4 = 0.20，末尾的 0 可以去掉，写成 0.2，小数的大小不变；但 1.02 × 3 = 3.06 中间的 0 不能去，去了就变成 3.6，错了十倍。",
            ],
        },
        {
            "kind": "concept",
            "title": "估算验算",
            "body": [
                "算完先估一估：2.9 × 4.1 可以看成 3 × 4 = 12，实际算得 11.89，跟 12 很接近，说明小数点没点错。",
                "如果算成 118.9 或 1.189，和 12 差了十倍，一眼就能发现是小数点的问题。估算不能代替计算，但能帮你快速检查。",
            ],
        },
    ],
    "pitfalls": [
        "积的小数位数数错：两个因数的小数位数要相加，不是取最多的那一个。",
        "位数不够不补零：0.02×0.3 写成 0.06，少补了一个 0，答案就大了十倍。",
        "把中间的 0 去掉：1.02×3=3.06，中间的 0 去掉就变成 3.6，错了。",
        "点小数点从左边数：必须从积的右边往左数，数够位数再点。",
        "算完不检查：先估一估，答案数量级不对就是小数点错了。",
    ],
    "summary": "小数乘法三句话：先按整数乘，数一数两个因数一共有几位小数，再从右往左点小数点。位数不够在前面补 0，末尾的 0 可以去掉，中间的 0 不能去。算完用估算检查一下小数点。",
    "questions": [
        {
            "prompt": "计算 2.5 × 3，结果是多少？",
            "options": ["75", "7.5", "0.75"],
            "answer": 1,
            "explanation": "先算 25×3=75，因数 2.5 有一位小数，积也点一位小数，得 7.5。写成 75 或 0.75 都是小数点位置错了。",
        },
        {
            "prompt": "计算 0.02 × 0.3，结果是多少？",
            "options": ["0.006", "0.06", "0.6"],
            "answer": 0,
            "explanation": "2×3=6，两个因数一共 2+1=3 位小数，6 只有一位，要在前面补两个 0，写成 0.006。",
        },
        {
            "prompt": "下面哪个结果可以去掉末尾的 0 而不改变大小？",
            "options": ["3.06", "0.20", "1.02"],
            "answer": 1,
            "explanation": "0.20 末尾的 0 去掉后是 0.2，大小不变；3.06 和 1.02 的 0 在中间，去掉就改变大小了。",
        },
        {
            "prompt": "估算 2.9 × 4.1，下面哪个结果最合理？",
            "options": ["1.189", "118.9", "11.89"],
            "answer": 2,
            "explanation": "把 2.9 看成 3、4.1 看成 4，3×4=12，所以 11.89 最接近；1.189 和 118.9 都差了一个数量级。",
        },
    ],
})

