        "会画平行四边形的高，知道高必须垂直于底，且有无数条",
        "知道梯形只有一组对边平行，认识上底、下底、腰和高",
        "认识等腰梯形，知道它两腰相等",
        "理清四边形、平行四边形、长方形、正方形、梯形的关系",
